// Paints the site in any of the built-in Omarchy palettes. Runs before first paint so a
// stored choice doesn't flash the default first, then adds the theme bar once the page is up.
// The list below is generated from the omarchy repo — run bin/build-palettes to refresh it.

// >>> themes (generated by bin/build-palettes)
const THEMES = [
  { slug: "catppuccin-latte", name: "Catppuccin Latte", mode: "light" },
  { slug: "catppuccin", name: "Catppuccin", mode: "dark" },
  { slug: "ethereal", name: "Ethereal", mode: "dark" },
  { slug: "everforest", name: "Everforest", mode: "dark" },
  { slug: "flexoki-light", name: "Flexoki Light", mode: "light" },
  { slug: "gruvbox", name: "Gruvbox", mode: "dark" },
  { slug: "hackerman", name: "Hackerman", mode: "dark" },
  { slug: "kanagawa", name: "Kanagawa", mode: "dark" },
  { slug: "last-horizon", name: "Last Horizon", mode: "dark" },
  { slug: "lumon", name: "Lumon", mode: "dark" },
  { slug: "lupine", name: "Lupine", mode: "light" },
  { slug: "matte-black", name: "Matte Black", mode: "dark" },
  { slug: "miasma", name: "Miasma", mode: "dark" },
  { slug: "nord", name: "Nord", mode: "dark" },
  { slug: "osaka-jade", name: "Osaka Jade", mode: "dark" },
  { slug: "retro-82", name: "Retro 82", mode: "dark" },
  { slug: "ristretto", name: "Ristretto", mode: "dark" },
  { slug: "rose-pine", name: "Rose Pine", mode: "light" },
  { slug: "solitude", name: "Solitude", mode: "dark" },
  { slug: "tokyo-night", name: "Tokyo Night", mode: "dark" },
  { slug: "vantablack", name: "Vantablack", mode: "dark" },
  { slug: "white", name: "White", mode: "light" }
];
// <<< themes

const STORAGE_KEY = "omarchy-theme";
const DEFAULT_THEME = "tokyo-night";

// Private browsing and blocked site data both throw on access rather than returning null
function readStored() {
  try { return localStorage.getItem(STORAGE_KEY); } catch { return null; }
}

function writeStored(slug) {
  try { localStorage.setItem(STORAGE_KEY, slug); } catch { /* the choice just won't persist */ }
}

function find(slug) {
  return THEMES.find((theme) => theme.slug === slug);
}

function preferred() {
  return find(readStored()) || find(DEFAULT_THEME);
}

function apply(theme) {
  selected = theme;
  document.documentElement.dataset.omarchyTheme = theme.slug;
  refresh();
}


// The one place the bar is brought back in step with the current choice
function refresh() {
  if (!bar) return;

  bar.querySelectorAll(".theme-bar__theme").forEach((button) => {
    button.setAttribute("aria-pressed", String(button.dataset.omarchyTheme === selected.slug));
  });

  bar.querySelector(".theme-bar__name").textContent = selected.name;
}

function buildBar() {
  bar = document.createElement("nav");
  bar.className = "theme-bar";
  bar.setAttribute("aria-label", "Site theme");

  const name = document.createElement("p");
  name.className = "theme-bar__name";

  const themes = document.createElement("div");
  themes.className = "theme-bar__themes";

  THEMES.forEach((theme) => {
    const button = document.createElement("button");

    // The palette rules are plain attribute selectors, so a button carrying the attribute
    // paints its own swatch in its own colors
    button.dataset.omarchyTheme = theme.slug;
    button.className = "theme-bar__theme";
    button.type = "button";
    button.title = theme.name;
    button.setAttribute("aria-label", theme.name);
    button.innerHTML = '<span class="theme-bar__swatch"></span>';

    button.addEventListener("click", () => {
      apply(theme);
      writeStored(theme.slug);
    });

    // Reading the name back on hover keeps 22 labels off the page without hiding them
    button.addEventListener("pointerenter", () => name.textContent = theme.name);
    button.addEventListener("focus", () => name.textContent = theme.name);

    themes.append(button);
  });

  bar.addEventListener("pointerleave", refresh);

  bar.append(themes, name);
  document.body.append(bar);
  refresh();
}

let selected;
let bar;

apply(preferred());

document.addEventListener("DOMContentLoaded", buildBar);
